-- Puts the initial lists split into levels in saved workspaces in their group (v0.79.0), as src/plugins/packs gives
-- them: the app shows the lists of a group as one and has the levels chosen when it is picked. A list is found by its
-- id, whether or not its words were changed since. A list that already has a group or levels keeps them, and a
-- workspace that would go over the size the app saves (MaxListsBytes) is left as it is. Earlier web screens and the Go
-- server keep fields they do not know, so they keep these when they save.
WITH pack AS (
  SELECT p->>'id' AS id, p->'group' AS "group", p->'levels' AS levels FROM jsonb_array_elements('[{"id":"un-member-states-chinese-193-beginner-1","group":"国名：中国語・国連加盟国","levels":["初級1"]},{"id":"un-member-states-chinese-193-beginner-2","group":"国名：中国語・国連加盟国","levels":["初級2"]},{"id":"un-member-states-chinese-193-intermediate","group":"国名：中国語・国連加盟国","levels":["中級"]},{"id":"un-member-states-chinese-193-advanced-1","group":"国名：中国語・国連加盟国","levels":["上級1"]},{"id":"un-member-states-chinese-193-advanced-2","group":"国名：中国語・国連加盟国","levels":["上級2"]},{"id":"linux-commands-basic-beginner","group":"Linuxコマンド","levels":["基本","初級"]},{"id":"linux-commands-basic-intermediate","group":"Linuxコマンド","levels":["基本","中級"]},{"id":"linux-commands-basic-advanced","group":"Linuxコマンド","levels":["基本","上級"]},{"id":"linux-commands-options-beginner","group":"Linuxコマンド","levels":["オプション","初級"]},{"id":"linux-commands-options-intermediate-1","group":"Linuxコマンド","levels":["オプション","中級1"]},{"id":"linux-commands-options-intermediate-2","group":"Linuxコマンド","levels":["オプション","中級2"]},{"id":"linux-commands-options-advanced","group":"Linuxコマンド","levels":["オプション","上級"]},{"id":"linux-commands-advanced-beginner","group":"Linuxコマンド","levels":["応用","初級"]},{"id":"linux-commands-advanced-intermediate-1","group":"Linuxコマンド","levels":["応用","中級1"]},{"id":"linux-commands-advanced-intermediate-2","group":"Linuxコマンド","levels":["応用","中級2"]},{"id":"linux-commands-advanced-advanced","group":"Linuxコマンド","levels":["応用","上級"]},{"id":"linux-shell-bash-beginner","group":"Linux：シェルとBash","levels":["初級"]},{"id":"linux-shell-bash-advanced","group":"Linux：シェルとBash","levels":["上級"]},{"id":"linux-system-beginner","group":"Linux：システムの仕組み","levels":["初級"]},{"id":"linux-system-intermediate-1","group":"Linux：システムの仕組み","levels":["中級1"]},{"id":"linux-system-intermediate-2","group":"Linux：システムの仕組み","levels":["中級2"]},{"id":"linux-system-advanced","group":"Linux：システムの仕組み","levels":["上級"]},{"id":"aws-cli-beginner","group":"AWS CLIコマンド","levels":["初級"]},{"id":"aws-cli-advanced","group":"AWS CLIコマンド","levels":["上級"]},{"id":"macos-zsh-beginner","group":"macOSターミナル（zsh）コマンド","levels":["初級"]},{"id":"macos-zsh-intermediate","group":"macOSターミナル（zsh）コマンド","levels":["中級"]},{"id":"macos-zsh-advanced","group":"macOSターミナル（zsh）コマンド","levels":["上級"]},{"id":"arch-linux-beginner","group":"Arch Linuxコマンド","levels":["初級"]},{"id":"arch-linux-intermediate","group":"Arch Linuxコマンド","levels":["中級"]},{"id":"arch-linux-advanced","group":"Arch Linuxコマンド","levels":["上級"]},{"id":"vim-beginner","group":"Vimコマンド","levels":["初級"]},{"id":"vim-intermediate","group":"Vimコマンド","levels":["中級"]},{"id":"vim-advanced","group":"Vimコマンド","levels":["上級"]},{"id":"go-syntax-beginner","group":"Go構文","levels":["初級"]},{"id":"go-syntax-intermediate","group":"Go構文","levels":["中級"]},{"id":"go-syntax-advanced","group":"Go構文","levels":["上級"]},{"id":"java-syntax-beginner","group":"Java構文","levels":["初級"]},{"id":"java-syntax-intermediate-1","group":"Java構文","levels":["中級1"]},{"id":"java-syntax-intermediate-2","group":"Java構文","levels":["中級2"]},{"id":"java-syntax-advanced","group":"Java構文","levels":["上級"]},{"id":"kotlin-syntax-beginner-1","group":"Kotlin構文","levels":["初級1"]},{"id":"kotlin-syntax-beginner-2","group":"Kotlin構文","levels":["初級2"]},{"id":"kotlin-syntax-intermediate","group":"Kotlin構文","levels":["中級"]},{"id":"kotlin-syntax-advanced-1","group":"Kotlin構文","levels":["上級1"]},{"id":"kotlin-syntax-advanced-2","group":"Kotlin構文","levels":["上級2"]},{"id":"un-member-states-chinese-193-lowercase-beginner-1","group":"国名：中国語・国連加盟国（小文字）","levels":["初級1"]},{"id":"un-member-states-chinese-193-lowercase-beginner-2","group":"国名：中国語・国連加盟国（小文字）","levels":["初級2"]},{"id":"un-member-states-chinese-193-lowercase-intermediate","group":"国名：中国語・国連加盟国（小文字）","levels":["中級"]},{"id":"un-member-states-chinese-193-lowercase-advanced-1","group":"国名：中国語・国連加盟国（小文字）","levels":["上級1"]},{"id":"un-member-states-chinese-193-lowercase-advanced-2","group":"国名：中国語・国連加盟国（小文字）","levels":["上級2"]},{"id":"postgresql-syntax-beginner","group":"PostgreSQL構文","levels":["初級"]},{"id":"postgresql-syntax-intermediate-1","group":"PostgreSQL構文","levels":["中級1"]},{"id":"postgresql-syntax-intermediate-2","group":"PostgreSQL構文","levels":["中級2"]},{"id":"postgresql-syntax-advanced","group":"PostgreSQL構文","levels":["上級"]},{"id":"prisma-syntax-beginner","group":"Prisma構文","levels":["初級"]},{"id":"prisma-syntax-advanced","group":"Prisma構文","levels":["上級"]},{"id":"jest-syntax-beginner","group":"Jest構文","levels":["初級"]},{"id":"jest-syntax-advanced","group":"Jest構文","levels":["上級"]},{"id":"playwright-syntax-beginner","group":"Playwright構文","levels":["初級"]},{"id":"playwright-syntax-advanced","group":"Playwright構文","levels":["上級"]},{"id":"typescript-syntax-beginner","group":"TypeScript構文","levels":["初級"]},{"id":"typescript-syntax-intermediate","group":"TypeScript構文","levels":["中級"]},{"id":"typescript-syntax-advanced","group":"TypeScript構文","levels":["上級"]},{"id":"hono-methods-beginner","group":"Honoメソッド","levels":["初級"]},{"id":"hono-methods-intermediate","group":"Honoメソッド","levels":["中級"]},{"id":"hono-methods-advanced","group":"Honoメソッド","levels":["上級"]},{"id":"php-syntax-beginner","group":"PHP構文","levels":["初級"]},{"id":"php-syntax-intermediate","group":"PHP構文","levels":["中級"]},{"id":"php-syntax-advanced","group":"PHP構文","levels":["上級"]},{"id":"rails-methods-beginner","group":"Railsメソッド","levels":["初級"]},{"id":"rails-methods-intermediate","group":"Railsメソッド","levels":["中級"]},{"id":"rails-methods-advanced","group":"Railsメソッド","levels":["上級"]},{"id":"express-methods-beginner","group":"Expressメソッド","levels":["初級"]},{"id":"express-methods-intermediate","group":"Expressメソッド","levels":["中級"]},{"id":"express-methods-advanced","group":"Expressメソッド","levels":["上級"]},{"id":"oracle-plsql-syntax-beginner","group":"Oracle PL/SQL構文","levels":["初級"]},{"id":"oracle-plsql-syntax-intermediate","group":"Oracle PL/SQL構文","levels":["中級"]},{"id":"oracle-plsql-syntax-advanced","group":"Oracle PL/SQL構文","levels":["上級"]},{"id":"sql-server-tsql-syntax-beginner","group":"SQL Server T-SQL構文","levels":["初級"]},{"id":"sql-server-tsql-syntax-intermediate","group":"SQL Server T-SQL構文","levels":["中級"]},{"id":"sql-server-tsql-syntax-advanced","group":"SQL Server T-SQL構文","levels":["上級"]}]'::jsonb) p
), rebuilt AS (
  SELECT w.owner_id, jsonb_agg(
    CASE WHEN pack.id IS NOT NULL AND jsonb_typeof(saved.list) = 'object' AND saved.list->'group' IS NULL AND saved.list->'levels' IS NULL
      THEN saved.list || jsonb_build_object('group', pack."group", 'levels', pack.levels)
      ELSE saved.list END
    ORDER BY saved.position) AS lists
  FROM "typle_workspaces" w
  CROSS JOIN LATERAL jsonb_array_elements(w.lists) WITH ORDINALITY AS saved(list, position)
  LEFT JOIN pack ON pack.id = saved.list->>'id'
  WHERE jsonb_typeof(w.lists) = 'array'
  GROUP BY w.owner_id
)
UPDATE "typle_workspaces" w
SET lists = rebuilt.lists, revision = w.revision + 1, updated_at = now()
FROM rebuilt
WHERE w.owner_id = rebuilt.owner_id
  AND rebuilt.lists <> w.lists
  AND octet_length(rebuilt.lists::text) <= 896 * 1024;
